cd /testbed && cat > /tmp/repro_display.py <<'EOF'
import django
from django.conf import settings
settings.configure(INSTALLED_APPS=[], DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3', 'NAME': ':memory:'}})
django.setup()

from django.db import models
from django.utils.translation import gettext_lazy as _


class FooBar(models.Model):
    foo_bar = models.CharField(_("foo"), choices=[(1, 'foo'), (2, 'bar')])

    def __str__(self):
        return self.get_foo_bar_display()

    def get_foo_bar_display(self):
        return "something"

    class Meta:
        app_label = 'repro'


class FooBarNoOverride(models.Model):
    foo_bar = models.CharField(_("foo"), choices=[(1, 'foo'), (2, 'bar')])

    class Meta:
        app_label = 'repro'


class Base(models.Model):
    field = models.CharField(max_length=10, choices=[('a', 'A')])

    def get_field_display(self):
        return 'override-in-abstract'

    class Meta:
        abstract = True


class Child(Base):
    class Meta:
        app_label = 'repro'


assert FooBar(foo_bar=1).get_foo_bar_display() == 'something', FooBar(foo_bar=1).get_foo_bar_display()
assert str(FooBar(foo_bar=1)) == 'something', str(FooBar(foo_bar=1))
assert FooBarNoOverride(foo_bar=1).get_foo_bar_display() == 'foo', FooBarNoOverride(foo_bar=1).get_foo_bar_display()
assert FooBarNoOverride(foo_bar=9).get_foo_bar_display() == 9
assert FooBarNoOverride(foo_bar=None).get_foo_bar_display() is None
assert Child(field='a').get_field_display() == 'override-in-abstract', Child(field='a').get_field_display()
print('ALL REPRO CHECKS PASSED')
EOF
python /tmp/repro_display.py && echo '--- running model tests ---' && python tests/runtests.py model_fields model_regress forms_tests.tests.tests -v1 2>&1 | tail -20
